let lessonId4=null;
function audioButton4(text,label='اسمع'){return `<button class="text-link" data-say="${esc(text)}" aria-label="${esc(label+' '+text)}">◖)) ${esc(label)}</button>`;}
function lessonCatalog4(){lessonId4=null;$('#app').innerHTML=`<div class="view-head"><h1>مسارات التعلّم</h1><p>افتح الدرس: كلمات، جمل وأسئلة، تصريفات، ثم تدريب.</p></div><div class="toolbar">${levelTabs()}</div><div class="lesson-grid">${filtered().map(t=>`<article class="panel"><span class="badge">${t.level}</span><h2>${esc(t.title)}</h2><p>${lessonWords4(t.id).length} كلمة • ${DIALOGUE4[t.id].length} سؤالًا وإجابة</p><p class="subtle">${esc((NOTES4[t.id]||t.explain).slice(0,130))}</p><button class="primary" data-lesson4="${t.id}">افتح الدرس ←</button></article>`).join('')}</div>`;}
function lessonPage4(id){const t=TOPICS.find(t=>t.id===id);if(!t)return;lessonId4=id;const words=lessonWords4(id),verbs=words.filter(w=>w.forms);$('#app').innerHTML=`<button class="text-link" onclick="go('paths')">← كل المسارات</button><div class="view-head"><span class="badge">${t.level}</span><h1>${esc(t.title)}</h1><p>${esc(NOTES4[id]||t.explain)}</p></div><div class="actions"><button class="secondary" onclick="audioSettings4()">إعدادات النطق</button><button class="primary" data-lesson-practice4="${id}">تدريب كلمات الدرس</button><button class="secondary" data-topic="${id}" data-kind="grammar">تطبيق القاعدة</button></div><h2>١. كلمات الدرس</h2><div class="lesson-grid">${words.map(w=>`<article class="panel"><h3 class="de" lang="de">${esc(w.de)}</h3><p>${esc(w.ar)}</p>${audioButton4(w.de,w.forms?'اسمع المصدر':'اسمع الكلمة')}<button class="text-link" data-word="${w.id}">التفاصيل والتدريب</button><a class="text-link" href="https://www.dict.cc/?s=${encodeURIComponent(w.de)}" target="_blank" rel="noopener noreferrer">نطق dict.cc ↗</a></article>`).join('')}</div><h2>٢. اسأل وجاوب</h2><p class="subtle">اسمع السؤال، جاوب بنفسك، ثم اكشف نموذج الإجابة وغيّر بياناته لتناسبك.</p>${DIALOGUE4[id].map(([q,a,ar])=>`<article class="panel lesson-dialogue"><p class="de" lang="de">${esc(q)} ${audioButton4(q,'اسمع السؤال')}</p><details><summary>اكشف نموذج الإجابة</summary><p class="de" lang="de">${esc(a)} ${audioButton4(a,'اسمع الإجابة')}</p><p>${esc(ar)}</p></details></article>`).join('')}${verbs.length?`<h2>٣. أفعال الدرس مع كل الضمائر</h2><p>المضارع هنا. افتح «باقي الأزمنة» للماضي والماضي المركب والمستقبل.</p>${verbs.map(w=>`<details class="panel"><summary><span lang="de">${esc(w.de)}</span> — ${esc(w.ar)}</summary>${audioButton4(w.de,'اسمع المصدر')}<div class="lesson-table-wrap"><table class="data-table" dir="ltr"><thead><tr><th>Pronomen</th><th>Präsens</th><th>Audio</th></tr></thead><tbody>${['ich','du','er','sie','es','wir','ihr','sie','Sie'].map((p,i)=>{const f=w.forms[[0,1,2,2,2,3,4,5,5][i]];return `<tr><td>${p}</td><td lang="de">${esc(f)}</td><td>${audioButton4(p+' '+f)}</td></tr>`;}).join('')}</tbody></table></div><button class="secondary" data-word="${w.id}">باقي الأزمنة والتفاصيل</button></details>`).join('')}`:''}<div class="panel"><h2>طبّق من عندك</h2><p>اكتب ثلاث جمل عن نفسك بالاستعانة بالدرس، ثم قلها بصوتك. هذه مساحة تدريب، وليست تصحيحًا آليًا.</p><textarea id="lesson-draft4" aria-label="جملتي" placeholder="Meine Sätze …"></textarea><p id="lesson-save4" aria-live="polite"></p></div>`;try{$('#lesson-draft4').value=localStorage.getItem('schritt-lesson-'+id)||'';}catch{}$('#lesson-draft4').oninput=e=>{try{localStorage.setItem('schritt-lesson-'+id,e.target.value);$('#lesson-save4').textContent='تم الحفظ على هذا المتصفح.';}catch{$('#lesson-save4').textContent='تعذّر الحفظ؛ انسخ النص قبل المغادرة.';}};bind();window.scrollTo(0,0);}
