bind=function(){bindBefore4();document.querySelectorAll('[data-lesson4]').forEach(b=>b.onclick=()=>lessonPage4(b.dataset.lesson4));document.querySelectorAll('[data-lesson-practice4]').forEach(b=>b.onclick=()=>startPractice('lesson',lessonWords4(b.dataset.lessonPractice4),'word'));};
const NAV_GROUPS4=[['تعلّم',['home','studyPlan','paths']],['تدرّب',['review','dialogues','speak','phonetics']],['مرجعك',['dictionary','verbs','grammarBook','sources']],['اختبر وتابع',['examCenter','quiz','progress']]];
function compactNav4(){$('#nav').innerHTML=NAV_GROUPS4.map(([label,ids])=>`<details class="nav-group4" ${ids.includes(view)?'open':''}><summary>${label}</summary>${ids.map(id=>navs.find(n=>n[0]===id)).filter(Boolean).map(([id,label])=>`<a href="#${id}" data-nav="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${esc(label)}</a>`).join('')}</details>`).join('');document.querySelectorAll('#nav [data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));}
const renderBefore4=render;render=function(){renderBefore4();compactNav4();};
let voicePref4={name:'',rate:1};try{voicePref4={...voicePref4,...JSON.parse(localStorage.getItem('schritt-voice4')||'{}')};}catch{}
function germanVoices4(){return 'speechSynthesis'in window?speechSynthesis.getVoices().filter(v=>/^de(?:[-_]|$)/i.test(v.lang)):[];}
function audioSettings4(){const voices=germanVoices4();modalWide(`<h2>إعدادات النطق الألماني</h2><p>الصوت هنا آلي؛ اختر الصوت الأنسب لجهازك. الأصوات المتصلة تحتاج الإنترنت. للمقارنة البشرية افتح dict.cc من بطاقة الكلمة.</p><label for="voice4">الصوت</label><select id="voice4"><option value="">اختيار تلقائي لصوت ألماني</option>${voices.map(v=>`<option value="${esc(v.name)}" ${v.name===voicePref4.name?'selected':''}>${esc(v.name)} — ${v.localService?'على الجهاز':'متصل بالإنترنت'}</option>`).join('')}</select><label for="rate4">السرعة</label><select id="rate4">${[0.75,0.9,1].map(r=>`<option ${r===voicePref4.rate?'selected':''} value="${r}">${r===1?'طبيعية':r===0.9?'أبطأ قليلًا':'بطيئة'}</option>`).join('')}</select><div class="actions">${audioButton4('spielen','اسمع المصدر spielen')}${audioButton4('Ich spiele.','اسمع Ich spiele')}${audioButton4('Wir spielen.','اسمع Wir spielen')}</div><p id="voice-status4" aria-live="polite">${voices.length?'اختر واستمع للمقارنة.':'لم يظهر صوت ألماني بعد. ثبّت صوتًا ألمانيًا على جهازك أو جرّب متصفحًا آخر، ثم أعد فتح الإعدادات.'}</p>`);const saveVoice=()=>{voicePref4={name:$('#voice4').value,rate:Number($('#rate4').value)};try{localStorage.setItem('schritt-voice4',JSON.stringify(voicePref4));}catch{}};$('#voice4').onchange=saveVoice;$('#rate4').onchange=saveVoice;}
say=function(text){if(typeof text!=='string'||!text.trim())return;if(!('speechSynthesis'in window)){audioSettings4();return;}const voices=germanVoices4(),v=voices.find(v=>v.name===voicePref4.name)||voices.find(v=>v.lang==='de-DE')||voices[0];if(!v){audioSettings4();return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.voice=v;u.lang=v.lang;u.rate=[0.75,0.9,1].includes(voicePref4.rate)?voicePref4.rate:1;u.onerror=e=>{if(!['canceled','interrupted'].includes(e.error))showModal('<h2>تعذّر تشغيل الصوت</h2><p>جرّب صوتًا ألمانيًا آخر من إعدادات النطق أو افتح رابط dict.cc للكلمة.</p>');};speechSynthesis.speak(u);};
const detailBefore4=wordDetail;wordDetail=function(id){detailBefore4(id);const w=allWords().find(w=>w.id===id);if(!w)return;$('#word-detail').insertAdjacentHTML('afterbegin',`<div class="actions">${audioButton4(w.de,w.forms?'اسمع المصدر':'اسمع الكلمة')}<button class="secondary" onclick="audioSettings4()">إعدادات النطق</button></div>`);bind();};
const phoneticsBefore4=phonetics;EXTRA_VIEWS.phonetics=function(){phoneticsBefore4();$('#app').insertAdjacentHTML('afterbegin','<button class="primary" onclick="audioSettings4()">اختيار الصوت والسرعة</button>');};
render();
